using System.Globalization;
using MiniStore.Application.Dtos.Sales;
using MiniStore.Domain.Entities;
using MiniStore.Domain.Interfaces;
namespace MiniStore.Application.Services;
public sealed class CustomerReturnReceiptService(ICustomerReturnReceiptRepository receipts,ICustomerReturnRequestRepository requests,ISalesDeliveryRepository deliveries,
 IProductRepository products,IWarehouseRepository warehouses,IStorageLocationRepository locations,InventoryTrackingService tracking,
 DocumentNumberService numbers,IUnitOfWork unitOfWork,ICurrentUserService currentUser)
{
 public async Task<List<CustomerReturnReceiptSummaryDto>>GetAllAsync(string?search){var requestMap=(await requests.GetAllAsync()).ToDictionary(x=>x.Id,x=>x.ReturnNumber);return(await receipts.GetAllAsync(search)).Select(x=>new CustomerReturnReceiptSummaryDto(x.Id,x.ReceiptNumber,x.CustomerReturnRequestId,requestMap.GetValueOrDefault(x.CustomerReturnRequestId,$"#{x.CustomerReturnRequestId}"),x.ReceiptDate,x.Status,x.TotalReceivedQuantity)).ToList();}
 public async Task<CustomerReturnReceiptDetailsDto?>GetAsync(int id){var x=await receipts.GetByIdAsync(id);if(x is null)return null;var request=await requests.GetByIdAsync(x.CustomerReturnRequestId);var wm=(await warehouses.GetAllAsync()).ToDictionary(y=>y.Id,y=>y.Name);var lm=(await locations.SearchAsync(null,null)).ToDictionary(y=>y.Id,y=>$"{y.Code} — {y.Name}");return new(){Id=x.Id,ReceiptNumber=x.ReceiptNumber,RequestId=x.CustomerReturnRequestId,RequestNumber=request?.ReturnNumber??$"#{x.CustomerReturnRequestId}",ReceiptDate=x.ReceiptDate,Notes=x.Notes,Status=x.Status,CancellationReason=x.CancellationReason,RowVersion=x.RowVersion,Lines=x.Lines.Select(l=>new CustomerReturnReceiptLineDto(l.Id,l.ProductCodeSnapshot,l.ProductNameSnapshot,wm.GetValueOrDefault(l.WarehouseId,"—"),l.StorageLocationId.HasValue?lm.GetValueOrDefault(l.StorageLocationId.Value,"—"):"—",l.ReceivedQuantity,l.Disposition,l.InspectionNotes,l.TrackingAllocations)).ToList(),History=x.History.OrderBy(h=>h.CreatedAtUtc).Select(h=>new CustomerReturnReceiptHistoryDto(h.FromStatus,h.ToStatus,h.Action,h.UserId,h.Reason,h.CreatedAtUtc)).ToList()};}
 public async Task<CustomerReturnReceiptCreatePageDto?>GetCreatePageAsync(int requestId,CreateCustomerReturnReceiptDto?form=null){var request=await requests.GetByIdAsync(requestId);if(request is null||request.Status!=CustomerReturnRequestStatus.Approved)return null;var committed=await receipts.GetActiveReceivedQuantitiesAsync(request.Id);var pm=(await products.GetAllAsync(null)).ToDictionary(x=>x.Id);var wm=(await warehouses.GetAllAsync()).ToDictionary(x=>x.Id,x=>x.Name);var lm=(await locations.SearchAsync(null,null)).ToDictionary(x=>x.Id,x=>$"{x.Code} — {x.Name}");return new(){RequestId=request.Id,RequestNumber=request.ReturnNumber,RequestDate=request.RequestDate,CustomerName=request.CustomerNameSnapshot,Form=form??new(){CustomerReturnRequestId=request.Id},Lines=request.Lines.Select(l=>new CustomerReturnReceiptEligibleLineDto(l.Id,l.ProductCodeSnapshot,l.ProductNameSnapshot,wm.GetValueOrDefault(l.WarehouseId,"—"),l.StorageLocationId.HasValue?lm.GetValueOrDefault(l.StorageLocationId.Value,"—"):"—",pm.GetValueOrDefault(l.ProductId)?.TrackingPolicy??ProductTrackingPolicy.None,l.StockQuantity,committed.GetValueOrDefault(l.Id),Math.Max(0,l.StockQuantity-committed.GetValueOrDefault(l.Id)))).Where(l=>l.RemainingQuantity>0).ToList()};}
 public async Task<int>CreateAsync(CreateCustomerReturnReceiptDto dto){CustomerReturnReceipt?created=null;await unitOfWork.ExecuteInTransactionAsync(async()=>{var request=await requests.GetByIdAsync(dto.CustomerReturnRequestId)??throw new InvalidOperationException("Customer return request was not found.");if(request.Status!=CustomerReturnRequestStatus.Approved)throw new InvalidOperationException("Only an approved customer return request can be received.");if(dto.ReceiptDate<request.RequestDate)throw new ArgumentException("Return receipt date cannot be earlier than the request date.");var selected=dto.Lines?.Where(x=>x.ReceivedQuantity>0).ToList()??[];if(selected.Count==0)throw new ArgumentException("Enter at least one positive received return quantity.");if(selected.GroupBy(x=>x.CustomerReturnRequestLineId).Any(x=>x.Count()>1))throw new ArgumentException("A return request line can appear only once per receipt.");var committed=await receipts.GetActiveReceivedQuantitiesAsync(request.Id);var prior=await receipts.GetByRequestAsync(request.Id);var lineMap=request.Lines.ToDictionary(x=>x.Id);var productMap=(await products.GetAllAsync(null)).ToDictionary(x=>x.Id);created=new(await numbers.GenerateAsync(DocumentNumberType.CustomerReturnReceipt,dto.ReceiptDate.ToDateTime(TimeOnly.MinValue)),request.Id,dto.ReceiptDate,dto.Notes,currentUser.UserId);foreach(var input in selected){if(!lineMap.TryGetValue(input.CustomerReturnRequestLineId,out var source))throw new InvalidOperationException("A selected line does not belong to this return request.");if(input.ReceivedQuantity+committed.GetValueOrDefault(source.Id)>source.StockQuantity)throw new InvalidOperationException("Received return quantity cannot exceed the request line remaining quantity.");var product=productMap.GetValueOrDefault(source.ProductId)??throw new InvalidOperationException("Return product was not found.");if(product.TrackingPolicy!=ProductTrackingPolicy.None)await ValidateTrackingAsync(product,input,source,request,prior);created.AddLine(new(source.Id,source.SalesDeliveryLineId,source.ProductId,source.WarehouseId,source.StorageLocationId,input.ReceivedQuantity,input.Disposition,input.InspectionNotes,input.TrackingAllocations,source.UnitCostSnapshot,source.ProductCodeSnapshot,source.ProductNameSnapshot));}await receipts.AddAsync(created);});return created!.Id;}
 public Task InspectAsync(CustomerReturnReceiptCommandDto dto)=>Change(dto,x=>x.Inspect(currentUser.UserId));
 public Task CancelAsync(CustomerReturnReceiptCommandDto dto)=>Change(dto,x=>x.Cancel(currentUser.UserId,dto.Reason??string.Empty));
 private Task Change(CustomerReturnReceiptCommandDto dto,Action<CustomerReturnReceipt> action)=>unitOfWork.ExecuteInTransactionAsync(async()=>{var x=await receipts.GetByIdAsync(dto.Id)??throw new InvalidOperationException("Customer return receipt was not found.");if(dto.RowVersion.Length==0||!x.RowVersion.SequenceEqual(dto.RowVersion))throw new InvalidOperationException("Customer return receipt was modified by another user. Reload and try again.");action(x);});
 private async Task ValidateTrackingAsync(Product product,CreateCustomerReturnReceiptLineDto input,CustomerReturnRequestLine source,CustomerReturnRequest request,List<CustomerReturnReceipt> prior){var requested=ParseAllocations(product,input.TrackingAllocations,input.ReceivedQuantity);var delivery=await deliveries.GetByIdAsync(request.SalesDeliveryId)??throw new InvalidOperationException("Source sales delivery was not found.");var issued=await tracking.GetIssuedAllocationsAsync(product.Id,source.WarehouseId,source.StorageLocationId,delivery.DeliveryNumber);var used=prior.Where(r=>r.Status!=CustomerReturnReceiptStatus.Cancelled).SelectMany(r=>r.Lines).Where(l=>l.CustomerReturnRequestLineId==source.Id).SelectMany(l=>ParseAllocations(product,l.TrackingAllocations,l.ReceivedQuantity)).GroupBy(x=>x.Identifier,StringComparer.OrdinalIgnoreCase).ToDictionary(x=>x.Key,x=>x.Sum(y=>y.Quantity),StringComparer.OrdinalIgnoreCase);foreach(var allocation in requested)if(allocation.Quantity+used.GetValueOrDefault(allocation.Identifier)>issued.GetValueOrDefault(allocation.Identifier))throw new InvalidOperationException("The selected lot or serial was not issued by the source delivery, or it is already assigned to another return receipt.");}
 private static List<(string Identifier,decimal Quantity)>ParseAllocations(Product product,string?value,decimal expected){var rows=(value??string.Empty).Split([',',';','\n','\r'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(rows.Length==0)throw new InvalidOperationException("Lot or serial allocations are required for the tracked return receipt.");var result=new List<(string,decimal)>();foreach(var row in rows){var at=row.LastIndexOf(':');var identifier=(at>0?row[..at]:row).Trim().ToUpperInvariant();var quantity=1m;if(at>0&&!decimal.TryParse(row[(at+1)..].Trim(),NumberStyles.Number,CultureInfo.InvariantCulture,out quantity))throw new InvalidOperationException("Use LOT:QUANTITY format for lot allocations.");if(identifier.Length==0||quantity<=0)throw new InvalidOperationException("Every tracked return receipt allocation requires an identifier and positive quantity.");if(product.TrackingPolicy==ProductTrackingPolicy.Serial&&quantity!=1)throw new InvalidOperationException("Every returned serial must have quantity one.");result.Add((identifier,quantity));}var grouped=result.GroupBy(x=>x.Item1,StringComparer.OrdinalIgnoreCase).Select(x=>(Identifier:x.Key,Quantity:x.Sum(y=>y.Item2))).ToList();if(grouped.Sum(x=>x.Quantity)!=expected)throw new InvalidOperationException("Tracked return receipt allocations must exactly equal the received quantity.");if(product.TrackingPolicy==ProductTrackingPolicy.Serial&&grouped.Count!=result.Count)throw new InvalidOperationException("Returned serial numbers must be unique.");return grouped;}
}
